* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #f2f4e8;
  background: #17252a;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #17252a;
  background-image: linear-gradient(rgba(76, 110, 108, .12) 1px, transparent 1px), linear-gradient(90deg, rgba(76, 110, 108, .12) 1px, transparent 1px);
  background-size: 24px 24px;
}

.lock-card {
  width: min(100%, 480px);
  padding: 36px clamp(20px, 7vw, 48px) 30px;
  text-align: center;
  background: #243b40;
  border: 2px solid #4c6e6c;
  border-radius: 18px;
  box-shadow: 0 18px 0 rgba(12, 21, 24, .3), 0 28px 60px rgba(0, 0, 0, .22);
}

.pixel-mark { display: grid; grid-template-columns: repeat(2, 12px); gap: 4px; justify-content: center; margin: 0 auto 20px; }
.pixel-mark span { width: 12px; height: 12px; background: #f2c14e; }
.pixel-mark span:nth-child(2), .pixel-mark span:nth-child(3) { background: #4c6e6c; }
.eyebrow { margin: 0 0 8px; color: #f2c14e; font-size: .8rem; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(1.65rem, 6vw, 2.1rem); line-height: 1.15; }
.intro { margin: 12px 0 28px; color: #c8d5ce; }

.dials { display: flex; justify-content: center; gap: clamp(12px, 5vw, 24px); margin-bottom: 26px; }
.dial { display: grid; justify-items: center; gap: 9px; width: 84px; }
.step-button {
  width: 56px;
  min-height: 44px;
  border: 2px solid #4c6e6c;
  border-radius: 10px;
  color: #f2f4e8;
  background: #17252a;
  font: inherit;
  cursor: pointer;
  transition: transform .12s ease, background-color .12s ease, border-color .12s ease;
}
.step-button:hover { background: #36545a; border-color: #f2c14e; }
.step-button:active { transform: translateY(2px); background: #4c6e6c; }
.step-button:focus-visible, .open-button:focus-visible { outline: 3px solid #f2c14e; outline-offset: 3px; }
.dial-value {
  display: grid;
  place-items: center;
  width: 78px;
  height: 88px;
  border: 3px solid #f2c14e;
  border-radius: 12px;
  color: #f2c14e;
  background: #17252a;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 3rem;
  font-weight: 800;
  line-height: 1;
  box-shadow: inset 0 0 0 4px rgba(242, 193, 78, .08);
}

.open-button { width: 100%; min-height: 54px; border: 0; border-radius: 10px; color: #17252a; background: #f2c14e; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s ease, background-color .12s ease; }
.open-button:hover { background: #ffd875; }
.open-button:active { transform: translateY(2px); background: #dda932; }
.status { min-height: 48px; margin: 16px 0 18px; color: #c8d5ce; line-height: 1.5; }
.status.success { color: #f2c14e; font-weight: 700; }
.status.error { color: #f2f4e8; }
.attempts { display: flex; align-items: center; justify-content: center; gap: 9px; padding: 14px; border-top: 1px solid #4c6e6c; color: #c8d5ce; }
.attempt-icon { color: #f2c14e; font-weight: 900; }
#failed-count { min-width: 2ch; color: #f2f4e8; font-variant-numeric: tabular-nums; font-weight: 800; }
.hint { margin: 2px 0 0; color: #9eb5ad; font-size: .9rem; }

@media (max-width: 400px) {
  .lock-card { padding-top: 28px; padding-bottom: 24px; }
  .dial { width: 76px; }
  .dial-value { width: 70px; height: 82px; }
}

@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

"use strict";

const combination = [0, 0, 0];
const dials = [...document.querySelectorAll(".dial")];
const failedCount = document.querySelector("#failed-count");
const status = document.querySelector("#status");
let failures = 0;

for (const dial of dials) {
  dial.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-step]");
    if (!button) return;

    const index = Number(dial.dataset.dial);
    const change = button.dataset.step === "up" ? 1 : -1;
    combination[index] = (combination[index] + change + 10) % 10;
    dial.querySelector(".dial-value").textContent = combination[index];
  });
}

document.querySelector("#open-lock").addEventListener("click", () => {
  const opened = combination.join("") === "372";
  status.classList.toggle("success", opened);
  status.classList.toggle("error", !opened);

  if (opened) {
    status.textContent = "Click! The lock opens. You found the combination!";
    return;
  }

  failures += 1;
  failedCount.textContent = failures;
  status.textContent = "The lock stays shut. Try another combination.";
});
